24	using namespace tirx;
25	using namespace ffi;
26	
27	class LowerMACAIntrin {
28	public:
29	  static PrimFunc Substitute(PrimFunc f) {
30	    Optional<Target> target = f->GetAttr<Target>(tvm::attr::kTarget);
31	    if (!target.defined() || !TargetIsMaca(target.value())) {
32	      return f;
33	    }
34	
35	    Optional<Map<String, Array<PrimExpr>>> l2_map =
36	        f->GetAttr<Map<String, Array<PrimExpr>>>(attr::kL2PersistentMap);
37	    if (!l2_map.defined()) {
38	      return f;
39	    }
40	
41	    Array<Stmt> prologue_stmts;
42	    for (const auto &kv : l2_map.value()) {
43	      Buffer buf = FindBufferByName(f, kv.first);
44	      if (!buf.defined()) {
45	        continue;
46	      }
47	
48	      const Array<PrimExpr> &args = kv.second;
49	      ICHECK_GE(args.size(), 2);
50	
51	      Array<PrimExpr> packed_args;
52	      packed_args.push_back(
53	          StringImm(tvm_maca_stream_set_access_policy_window));
54	      packed_args.push_back(MakeBasePtr(buf));
55	      packed_args.push_back(args[1]);
56	      packed_args.push_back(args[0]);
57	      prologue_stmts.push_back(Evaluate(
58	          Call(DataType::Int(32), builtin::tvm_call_packed(), packed_args)));
59	    }
60	
61	    if (prologue_stmts.empty()) {
62	      return f;
63	    }
64	
65	    Array<PrimExpr> reset_args;
66	    reset_args.push_back(StringImm(tvm_maca_stream_reset_access_policy_window));
67	    Stmt epilogue_stmt = Evaluate(
68	        Call(DataType::Int(32), builtin::tvm_call_packed(), reset_args));
69	
70	    PrimFuncNode *fptr = f.CopyOnWrite();
71	    Stmt prologue = prologue_stmts.size() == 1 ? prologue_stmts[0]
72	                                               : SeqStmt(prologue_stmts);
73	    fptr->body = SeqStmt({prologue, fptr->body, epilogue_stmt});
74	    return f;
75	  }
76	
77	private:
78	  static Buffer FindBufferByName(const PrimFunc &f, const String &name) {
79	    for (const auto &kv : f->buffer_map) {
80	      if (kv.second->name == name) {
81	        return kv.second;
82	      }
83	    }
84	    return Buffer();
85	  }
86	
87	  static PrimExpr MakeBasePtr(const Buffer &buf) {
88	    PrimExpr base_ptr = buf->data;
89	    if (buf->elem_offset.defined() && !is_zero(buf->elem_offset)) {
90	      PrimExpr byte_offset = buf->elem_offset * IntImm(buf->elem_offset.dtype(),
91	                                                       buf->dtype.bytes());
92	      base_ptr = Call(DataType::Handle(), builtin::handle_add_byte_offset(),
93	                      {base_ptr, byte_offset});
94	    }
95	    return base_ptr;
96	  }
97	};
