99	using namespace tirx::transform;
100	
101	tvm::transform::Pass LowerMACAIntrin() {
102	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
103	    return LowerMACAIntrin::Substitute(f);
104	  };
105	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerMACAIntrin", {});
106	}
