36	struct MACAMath {
37	  std::string operator()(DataType t, std::string name) const {
38	    if (t.is_float()) {
39	      switch (t.bits()) {
40	      case 64:
41	        return name;
42	      case 32:
43	        return name + 'f';
44	      case 16: {
45	        if (name == "fabs") {
46	          return "__habs";
47	        } else if (name == "round") {
48	          return "hrint";
49	        } else {
50	          return "h" + name;
51	        }
52	      }
53	      default:
54	        return "";
55	      }
56	    } else if (t.is_bfloat16()) {
57	      if (name == "fabs") {
58	        return "__habs";
59	      }
60	      return 'h' + name;
61	    } else if (t.is_int() || t.is_uint()) {
62	      switch (t.bits()) {
63	      case 32:
64	        return "__" + name;
65	      case 64:
66	        return "__" + name + "ll";
67	      default:
68	        return "";
69	      }
70	    }
71	    return "";
72	  }
73	};
74	
75	struct MACAFastMath : public MACAMath {
76	  std::string operator()(DataType t, std::string name) const {
77	    if (t.is_float() && t.bits() == 32) {
78	      return "__" + name + 'f';
79	    } else {
80	      return MACAMath::operator()(t, name);
81	    }
82	    return "";
83	  }
84	};
85	
86	struct MACAFastMathTan : public MACAMath {
87	  std::string operator()(DataType t, std::string name) const {
88	    if (t.is_float()) {
89	      switch (t.bits()) {
90	      case 64:
91	        return name;
92	      // `__tanf` seems to produce some values too deviant from numpy tan
93	      // version. So, let's use just `tanf` instead.
94	      case 32:
95	        return "__" + name + 'f';
96	      case 16:
97	        return 'h' + name;
98	      default:
99	        return "";
100	      }
101	    }
102	    return "";
103	  }
104	};
105	
106	struct MACAPopcount {
107	  std::string operator()(DataType t, std::string name) const {
108	    if (t.is_uint()) {
109	      switch (t.bits()) {
110	      case 32:
111	        return "__popc";
112	      case 64:
113	        return "__popcll";
114	      default:
115	        return "";
116	      }
117	    }
118	    return "";
119	  }
120	};
121	
122	struct MACARound {
123	  std::string operator()(DataType t, std::string name) const {
124	    if (t.is_float()) {
125	      switch (t.bits()) {
126	      case 64:
127	        return "nearbyint";
128	      case 32:
129	        return "nearbyintf";
130	      case 16:
131	        return "hrint";
132	      default:
133	        return "";
134	      }
135	    } else if (t.is_bfloat16()) {
136	      return "hrint";
137	    }
138	    return "";
139	  }
140	};
