142	struct MACAWarpIntrinsic {
143	  const Op operator()(DataType t, const Op &orig_op) const {
144	    if (orig_op.same_as(builtin::tvm_warp_shuffle())) {
145	      return Op::Get("tirx.maca.__shfl_sync");
146	    } else if (orig_op.same_as(builtin::tvm_warp_shuffle_up())) {
147	      return Op::Get("tirx.maca.__shfl_up_sync");
148	    } else {
149	      ICHECK(orig_op.same_as(builtin::tvm_warp_shuffle_down()));
150	      return Op::Get("tirx.maca.__shfl_down_sync");
151	    }
152	  }
153	};
