155	static PrimExpr DispatchMACAWarpActiveMask(const PrimExpr &e) {
156	  const CallNode *call = e.as<CallNode>();
157	  return Call(call->dtype, Op::Get("tirx.maca.__activemask"), call->args);
158	}
