160	static PrimExpr DispatchMACAIsFinite(const PrimExpr &e) {
161	  const CallNode *call = e.as<CallNode>();
162	  ICHECK(call != nullptr);
163	  ICHECK_EQ(call->args.size(), 1U);
164	
165	  DataType arg_dtype = call->args[0].dtype();
166	  if (arg_dtype.is_float() &&
167	      (arg_dtype.bits() == 32 || arg_dtype.bits() == 64)) {
168	    ffi::Array<PrimExpr> new_args = {StringImm("isfinite"), call->args[0]};
169	    return Call(call->dtype, builtin::call_pure_extern(), new_args);
170	  }
171	
172	  return e;
173	}
