175	template <typename T> static PrimExpr DispatchMACAShuffle(const PrimExpr &e) {
176	  const CallNode *call = e.as<CallNode>();
177	  ICHECK(call != nullptr);
178	  ICHECK_EQ(call->args.size(), 5); // mask, value, warp_id, width, warp_size
179	  ffi::Array<PrimExpr> maca_args{
180	      {call->args[0], call->args[1], call->args[2], call->args[3]}};
181	  return Call(call->dtype, T()(call->dtype, Downcast<Op>(call->op)), maca_args);
182	}
