8	std::string ExtractStringWithPrefix(const std::string &str,
9	                                    const std::string &prefix) {
10	  if (str.find(prefix) != 0)
11	    return "";
12	  std::size_t pos = prefix.length();
13	  while (pos < str.length() &&
14	         (std::isdigit(str[pos]) || std::isalpha(str[pos]))) {
15	    ++pos;
16	  }
17	  return str.substr(prefix.length(), pos - prefix.length());
18	}
