20	void CheckOrSetAttr(ffi::Map<ffi::String, ffi::Any> *attrs,
21	                    const ffi::String &name, const ffi::String &value) {
22	  auto iter = attrs->find(name);
23	  if (iter == attrs->end()) {
24	    attrs->Set(name, value);
25	  } else {
26	    auto str = (*iter).second.try_cast<ffi::String>();
27	    TVM_FFI_CHECK(str && str.value() == value, ValueError)
28	        << "Expects \"" << name << "\" to be \"" << value
29	        << "\", but gets: " << (*iter).second;
30	  }
31	}
