35	 * \param target The Target to update
36	 * \return The updated attributes
37	 */
38	ffi::Map<ffi::String, ffi::Any>
39	UpdateMACAAttrs(ffi::Map<ffi::String, ffi::Any> target) {
40	  CheckOrSetAttr(&target, "mtriple", "mxc-metax-macahca");
41	  // Update -mcpu=xcore1000
42	  std::string arch = "xcore1000";
43	  if (target.count("mcpu")) {
44	    ffi::String mcpu = Downcast<ffi::String>(target.at("mcpu"));
45	    arch = ExtractStringWithPrefix(mcpu, "xcore");
46	    TVM_FFI_CHECK(!arch.empty(), ValueError)
47	        << "MACA target gets an invalid XCORE version: -mcpu=" << mcpu;
48	  } else {
49	    if (auto f_get_maca_arch =
50	            tvm::ffi::Function::GetGlobal("tvm_callback_maca_get_arch")) {
51	      arch = (*f_get_maca_arch)().cast<std::string>();
52	    }
53	    target.Set("mcpu", ffi::String(arch));
54	  }
55	
56	  return target;
57	}
