31	  }
32	
33	  if (op.c_->dtype == DataType::Float(16)) {
34	    if (op.a_->dtype == DataType::Float(16) &&
35	        op.b_->dtype == DataType::Float(16))
36	      return op.k_ % 16 == 0;
37	    if (op.a_->dtype.is_float8() && op.b_->dtype.is_float8())
38	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
39	    return false;
40	  }
41	  if (op.c_->dtype == DataType::Float(32)) {
42	    if (op.a_->dtype == DataType::Float(16) &&
43	        op.b_->dtype == DataType::Float(16))
44	      return op.k_ % 16 == 0;
45	    if (op.a_->dtype == DataType::BFloat(16) &&
46	        op.b_->dtype == DataType::BFloat(16))
47	      return op.k_ % 16 == 0;
48	    if (op.a_->dtype == DataType::Float(32) &&
49	        op.b_->dtype == DataType::Float(32))
50	      return (!op.transA_) && op.transB_ && op.k_ % 8 == 0;
51	    if (op.a_->dtype.is_float8() && op.b_->dtype.is_float8())
52	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
53	    return false;
54	  }
55	  if (op.c_->dtype == DataType::Int(32)) {
56	    if (op.a_->dtype == DataType::Int(8) && op.b_->dtype == DataType::Int(8))
57	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
58	    if (op.a_->dtype == DataType::Int(8) && op.b_->dtype == DataType::UInt(8))
59	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
60	    if (op.a_->dtype == DataType::UInt(8) && op.b_->dtype == DataType::Int(8))
61	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
62	    if (op.a_->dtype == DataType::UInt(8) && op.b_->dtype == DataType::UInt(8))
63	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
64	    return false;
65	  }
66	  return false;
